// véu escuro da classe tvc-art-foto-*). O 6º item (o prompt) só documenta como a foto foi feita; o catálogo não usa.
// Os nomes das empresas são fictícios. Nada de marcas reais.

const P = (s) => s; // o prompt (assunto da foto); o estilo comum vai junto na geração (veja PROMPT_STYLE)
